body.script:
        (function () {
          var msg = document.getElementById("msg");
          var sp = document.getElementById("sp");
          var CACHE = "xylora.host";
          var PROBE_MS = 4500;
          var BAKED = ["https://xylora.org"];

          function say(t) { try { msg.textContent = t; } catch (e) {} }
          function norm(h) {
            var s = ("" + h).trim().replace(/\/+$/, "");
            return /^https?:\/\//.test(s) ? s : "https://" + s;
          }
          function remembered() {
            try { return localStorage.getItem(CACHE) || ""; } catch (e) { return ""; }
          }
          function remember(h) {
            try { localStorage.setItem(CACHE, h); } catch (e) {}
          }

          function loadHosts() {
            var here = (document.currentScript && document.currentScript.src) || location.href;
            var url = here.replace(/[^/]*(?:[?#].*)?$/, "") + "apis.json";
            return fetch(url, { cache: "no-store" })
              .then(function (r) { return r.ok ? r.json() : null; })
              .then(function (j) {
                var list = (j && Array.isArray(j.hosts)) ? j.hosts : [];
                return list.length ? list.concat(BAKED) : BAKED;
              })
              .catch(function () { return BAKED; });
          }

          function withTimeout(p, ms) {
            return new Promise(function (resolve) {
              var done = false;
              var t = setTimeout(function () { if (!done) { done = true; resolve(false); } }, ms);
              p.then(function (v) { if (!done) { done = true; clearTimeout(t); resolve(v); } },
                     function () { if (!done) { done = true; clearTimeout(t); resolve(false); } });
            });
          }

          function ping(host) {
            return withTimeout(
              fetch(host + "/", { cache: "no-store", mode: "no-cors" })
                .then(function () { return true; }),
              PROBE_MS
            );
          }

          function go(host) {
            remember(host);
            say("Opening…");
            location.replace(host + "/");
          }

          function firstThatPasses(hosts) {
            return new Promise(function (resolve) {
              var left = hosts.length, won = false;
              if (!left) return resolve(null);
              hosts.forEach(function (h) {
                ping(h).then(function (ok) {
                  if (won) return;
                  if (ok) { won = true; resolve(h); return; }
                  if (--left === 0) resolve(null);
                });
              });
            });
          }

          loadHosts().then(function (raw) {
            var seen = {}, hosts = [];
            [remembered()].concat(raw).forEach(function (h) {
              if (!h) return;
              var n = norm(h);
              if (!seen[n]) { seen[n] = 1; hosts.push(n); }
            });
            firstThatPasses(hosts).then(function (hit) {
              if (hit) return go(hit);
              sp.style.display = "none";
              msg.className = "msg err";
              say("Couldn't reach Xylora right now. Check your connection and try again.");
            });
          });
        })();
